}

#main-canvas,
#fog-canvas,
#movement-canvas,
#effects-canvas {
    image-rendering: optimizeSpeed;
    image-rendering: -moz-crisp-edges;
    image-rendering: -webkit-optimize-contrast;
    image-rendering: -o-crisp-edges;
    -ms-interpolation-mode: nearest-neighbor;
    position: absolute;
    left: 0;
    top: 0
}

#main-canvas {
    z-index: 1
}

#effects-canvas {
    z-index: 2
}

#movement-canvas {
    z-index: 3
}

#fog-canvas {
    z-index: 4
}

#click-layer {
    position: absolute;
    left: 0;
    right: 0;
    top: 0;
    bottom: 0;
    z-index: 5
}

a {
