    width: 84px;
    padding: 2px 0 2px 24px;
    white-space: nowrap;
}

.preset-wrap .box-time-sub .time-icon {
    position: absolute;
    top: 0;
    left: 2px
}

.preset-wrap .box-time-sub.time-attack {
    color: #f3a9a9
}

.preset-wrap .box-time-sub.time-support {
    color: #a9d1f3
}

.preset-wrap .combat-strength {
    line-height: 34px
}

.pre-wrap {
    white-space: pre-wrap
}

.btn-toggle-mobile {
    display: none
}

.btn-add-units {
    height: 87px
}

.building_resource_image {
    width: 100px;
    padding: 0;
    height: 100px;
    background-image: url("/img/dummy/building_dummy.png");
    background-position: 0 0;
    background-repeat: no-repeat
}

#map {
    user-select: none;
}

#map canvas {
    cursor: url("../../img/cursor/grab_d163924ec7.cur"), url("data:image/png;base64,"), auto;
}

#map canvas.icon {
    cursor: url("../../img/cursor/normal_17fc286c00.cur"), url("data:image/png;base64,"), auto
}

#map canvas:active {
    cursor: url("../../img/cursor/grab_pushed_26350ae50c.cur"), url("data:image/png;base64,"), auto;
}

#map canvas:active.icon {
    cursor: url("../../img/cursor/normal_17fc286c00.cur"), url("data:image/png;base64,"), auto
}

#map .map-bubble {
    width: 300px;
    height: 0;
    position: absolute;
    z-index: 6;
    margin-top: -50px;
    top: 0;
    left: 0;
}

#map .map-bubble .btn-click {
    width: 100%;
    height: 42px;
    line-height: 42px;
    font-size: 20px;
    margin-top: 8px;
    z-index: 2
}

.pre-wrap {
    white-space: pre-wrap
}

.btn-toggle-mobile {
    display: none
}

.btn-add-units {
    height: 87px
}














